// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        if (newOwner != address(0)) {
            c.transferOwnership(newOwner);
            address reportedOwner = c.owner();
            assertTrue(reportedOwner == newOwner);
        } else {
            c.renounceOwnership();
            address reportedOwner = c.owner();
            assertTrue(reportedOwner == address(0));
        }
    }
}
